   109	  const minutes = Math.floor((seconds % 3600) / 60)
   110	  const rest = seconds % 60
   111	  const parts: string[] = []
   112	  if (hours > 0) parts.push(`${hours}h`)
   113	  if (minutes > 0) parts.push(`${minutes}m`)
   114	  if (rest > 0 || parts.length === 0) parts.push(`${rest}s`)
   115	  return parts.join('')
