   129	  const counts = DISPOSITIONS
   130	    .map(disposition => [disposition, findings.filter(finding => finding.disposition === disposition).length] as const)
   131	    .filter(([, count]) => count > 0)
   132	    .map(([disposition, count]) => `${count} ${disposition}`)
